replace(p, "        <IconTemperature
          className="dashboard-nav__icon app-bottom-nav__icon"
          aria-hidden="true"
        />", "        <IconPlug
          className="dashboard-nav__icon app-bottom-nav__icon"
          aria-hidden="true"
        />")
for filename, old, new in [
