};
")
replace(p, "  onAddAutomation(kind: AppNavigationKind): void;", "  onAddAutomation(kind: AppNavigationKind, shellyId?: string): void;")
replace(p, "  const installations = useInstalledAutomationStore((state) => state.installations);
  const queryClient = useQueryClient();
  const hasClimate = installations.some((installation) => installation.kind !== 'time');", "  const installations = useInstalledAutomationStore((state) => state.installations);
  const shellyDevices = useHardwareSetupDraftStore((state) => state.shellyDevices);
  const queryClient = useQueryClient();
  const climateInstallations = installations.filter(
    (installation): installation is ClimateInstalledAutomation => installation.kind !== 'time'
  );
  const hasClimate = shellyDevices.length > 0 || climateInstallations.length > 0;")
replace(p, "  const visibleInstallations = installations.filter((installation) =>
    activeKind === 'time' ? installation.kind === 'time' : installation.kind !== 'time'
  );

  return (", "  const visibleInstallations = installations.filter((installation) =>
    activeKind === 'time' ? installation.kind === 'time' : installation.kind !== 'time'
  );
  const normalizedBaseUrl = (value: string) => value.trim().replace(/\/+$/, '').toLowerCase();
  const matchedClimateInstallationIds = new Set<string>();
  const plugEntries = shellyDevices.map((device) => {
    const installation =
      climateInstallations.find(
        (candidate) => normalizedBaseUrl(candidate.shelly.baseUrl) === normalizedBaseUrl(device.baseUrl)
      ) ?? null;
    if (installation) matchedClimateInstallationIds.add(installation.id);
    return { device, installation };
  });
  const unmatchedClimateInstallations = climateInstallations.filter(
    (installation) => !matchedClimateInstallationIds.has(installation.id)
  );
  const hasPlugEntries = plugEntries.length > 0 || unmatchedClimateInstallations.length > 0;

  return (")
