                <ClimateAutomationCard key={installation.id} installation={installation} onOpen={onOpenInstallation} />
              ) : (
                <PlainPlugCard
                  key={`plug:${device.id}`}
                  device={device}
                  onAddAutomation={() => onAddAutomation('climate', device.id)}
